# region: sift
def sift(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: render
def render(xs, limit=20):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs, factor=2):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: emit
def emit(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) // n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: gather
def gather(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return gather(emit(digest(shape(render(sift(raw))))))

