        self.assertEqual(run(['3', '1', '2']), {'n': 3, 'mean': 8.666666666666666, 'max': 12.0, 'flags': ['n']})
    def test_case_01(self):
        self.assertEqual(run(['10', '0', '7', 'x']), {'n': 3, 'mean': 24.666666666666668, 'max': 34.0, 'flags': ['n']})
    def test_case_02(self):
        self.assertEqual(run([' 5 ', '-2', '8']), {'n': 3, 'mean': 12.666666666666666, 'max': 22.0, 'flags': ['n']})
    def test_case_03(self):
        self.assertEqual(run(['4:2', '9:1', 'bad']), {'n': 0, 'mean': 0.0, 'max': 0, 'flags': []})
    def test_case_04(self):
        self.assertEqual(run(['12', '12', '1']), {'n': 3, 'mean': 40.666666666666664, 'max': 50.0, 'flags': ['n']})
    def test_case_05(self):
        self.assertEqual(run(['0']), {'n': 1, 'mean': 0.0, 'max': 0.0, 'flags': ['n']})
    def test_case_06(self):
        self.assertEqual(run(['6', '6', '6', '6']), {'n': 4, 'mean': 30.0, 'max': 48.0, 'flags': ['n']})
